// Copies the wire types generated by orbyn-engine into src/generated/.
// With --check it copies nothing and fails if src/generated differs from the engine's bindings.
// The engine checkout must be at the pinned commit (the one in src/generated/wasm/manifest.json), the same engine the wasm package and
// the end-to-end job use, so the wire types change only with a deliberate pin bump, never because engine main moved.
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const check = process.argv.includes("--check");
const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const dir = process.env.ORBYN_ENGINE_DIR;
if (!dir) {
  console.error("generate: set ORBYN_ENGINE_DIR to an orbyn-engine checkout that has built its contracts.");
  process.exit(1);
}
const pinned = JSON.parse(readFileSync(join(root, "src/generated/wasm/manifest.json"), "utf8")).engine;
const head = spawnSync("git", ["-C", resolve(dir), "rev-parse", "--verify", "HEAD"], { encoding: "utf8" });
if (head.status !== 0 || head.stdout.trim() !== pinned) {
  console.error(`generate: ${resolve(dir)} is at ${head.status === 0 ? head.stdout.trim() : "no readable commit"}, not the pinned engine ${pinned} (src/generated/wasm/manifest.json).\nCheck the engine out at the pinned commit. To move the pin, run npm run wasm on Linux first, then generate from that same commit.`);
  process.exit(1);
}
const from = join(resolve(dir), "crates/orbyn-contracts/bindings");
const to = join(root, "src/generated");

if (!existsSync(from)) {
  console.error(`generate: no bindings at ${from}\nBuild the engine's contracts first, or point ORBYN_ENGINE_DIR at the right checkout.`);
  process.exit(1);
}
const files = readdirSync(from).filter((f) => f.endsWith(".ts"));
if (files.length === 0) {
  console.error(`generate: no .ts files in ${from}`);
  process.exit(1);
}

if (check) {
  const have = existsSync(to) ? readdirSync(to).filter((f) => f.endsWith(".ts")) : [];
  const stale = [
    ...files.filter((f) => !have.includes(f) || readFileSync(join(from, f), "utf8") !== readFileSync(join(to, f), "utf8")),
    ...have.filter((f) => !files.includes(f)),
  ];
  if (stale.length > 0) {
    console.error(`generate:check: src/generated is out of date (${stale.join(", ")}). Run npm run generate.`);
    process.exit(1);
  }
  console.log(`generate:check: ${files.length} file(s) match ${from}`);
} else {
  mkdirSync(to, { recursive: true });
  for (const f of files) writeFileSync(join(to, f), readFileSync(join(from, f)));
  console.log(`generate: copied ${files.length} file(s) from ${from}`);
}
